UPDATE "QuestionBankItem" SET
  scenario = $s3$A 4-year-old boy presents to the pediatric clinic with a 3-day history of fever, cough, and a runny nose. His mother reports that he has been increasingly irritable and has had difficulty sleeping. On examination, his temperature is 101.5°F (38.6°C), respiratory rate is 24 breaths per minute, and he has bilateral wheezing on auscultation. A rapid antigen test for influenza is negative. He received nebulized albuterol an hour ago with little relief, he is using accessory muscles, and his oxygen saturation is 91% on room air.$s3$, "references" = $r3$[{"label": "MedlinePlus. Asthma control medicines are taken every day to reduce airway inflammation. A severe attack that does not respond to quick-relief medicine needs emergency care.", "url": "https://medlineplus.gov/asthma.html"}]$r3$::jsonb, "contentHash" = 'a81451025208af8a14ec75039d5d93cc7149f94343aac6b6289f5f5872cf13f2', manual_correction = true, "generationMeta" = CASE WHEN "generationMeta" IS NULL THEN '{"manualCorrection": true}'::jsonb WHEN jsonb_typeof("generationMeta")='object' THEN jsonb_set("generationMeta", '{manualCorrection}', 'true'::jsonb, true) ELSE "generationMeta" END, "updatedAt" = NOW()
