UPDATE "QuestionBankItem" SET
  scenario = $s4$A 5-year-old boy presents to the pediatric clinic with a 2-day history of fever, cough, and a runny nose. His mother reports that he has been more irritable than usual and has had difficulty sleeping. On examination, his temperature is 39.0°C (102.2°F), respiratory rate is 30 breaths per minute, and he has diffuse wheezing on auscultation. A rapid antigen test for influenza is negative. His oxygen saturation is 97% on room air. He is speaking in full sentences and has not yet received a bronchodilator.$s4$, "references" = $r4$[{"label": "MedlinePlus. Quick-relief asthma medicines open the airways during symptoms. Daily control medicines reduce airway inflammation.", "url": "https://medlineplus.gov/asthma.html"}]$r4$::jsonb, "contentHash" = '52273fccf3c258404a2dfc59f424caeae69fa2363f29a1ce0530073bf819bb0e', manual_correction = true, "generationMeta" = CASE WHEN "generationMeta" IS NULL THEN '{"manualCorrection": true}'::jsonb WHEN jsonb_typeof("generationMeta")='object' THEN jsonb_set("generationMeta", '{manualCorrection}', 'true'::jsonb, true) ELSE "generationMeta" END, "updatedAt" = NOW()
