UPDATE "QuestionBankItem" SET
  explanation = $e10$Non-inferiority is judged against a prespecified absolute margin, not against a superiority p value. Here the upper bound of the 95% confidence interval for the difference is 0.9%, which is below the 1.5% margin, so non-inferiority is met. The secondary superiority test has p=0.42, so a superiority claim is not supported.$e10$, "references" = $r10$[{"label": "Open-access commentary on interpreting a non-inferiority trial. Non-inferiority is judged against a prespecified absolute margin.", "url": "https://www.ebi.ac.uk/europepmc/webservices/rest/PMC13579575/fullTextXML"}]$r10$::jsonb, manual_correction = true, "generationMeta" = CASE WHEN "generationMeta" IS NULL THEN '{"manualCorrection": true}'::jsonb WHEN jsonb_typeof("generationMeta")='object' THEN jsonb_set("generationMeta", '{manualCorrection}', 'true'::jsonb, true) ELSE "generationMeta" END, "updatedAt" = NOW()
