UPDATE "QuestionBankItem" SET
  explanation = $e11$Nightly awakenings and hourly use of a short-acting beta-agonist mean this asthma is poorly controlled. Daily control medicines reduce airway inflammation and should be increased. A severe attack that does not respond to quick-relief medicine needs urgent care, which can include a systemic corticosteroid. He is still speaking in sentences with an oxygen saturation of 93%, so the immediate plan is to step up the controller and give an action plan.$e11$, "references" = $r11$[{"label": "MedlinePlus. Asthma control medicines are taken every day and reduce airway inflammation. A severe attack that does not respond to quick-relief medicine needs emergency care.", "url": "https://medlineplus.gov/asthma.html"}]$r11$::jsonb, manual_correction = true, "generationMeta" = CASE WHEN "generationMeta" IS NULL THEN '{"manualCorrection": true}'::jsonb WHEN jsonb_typeof("generationMeta")='object' THEN jsonb_set("generationMeta", '{manualCorrection}', 'true'::jsonb, true) ELSE "generationMeta" END, "updatedAt" = NOW()
