UPDATE "QuestionBankItem" SET
  explanation = $e12$Fever, a productive cough, tachycardia, and an oxygen saturation of 90% on the second day after hip repair point to a pulmonary source. Atelectasis is common after surgery and is treated by re-expanding the lung, including with incentive spirometry. Pneumonia can follow atelectasis, so chest imaging is needed and antibiotics are added if pneumonia is present.$e12$, "references" = $r12$[{"label": "MedlinePlus Medical Encyclopedia. Atelectasis is common after surgery. Treatment includes incentive spirometry, chest imaging is used, and pneumonia may develop in the collapsed area.", "url": "https://medlineplus.gov/ency/article/000065.htm"}]$r12$::jsonb, manual_correction = true, "generationMeta" = CASE WHEN "generationMeta" IS NULL THEN '{"manualCorrection": true}'::jsonb WHEN jsonb_typeof("generationMeta")='object' THEN jsonb_set("generationMeta", '{manualCorrection}', 'true'::jsonb, true) ELSE "generationMeta" END, "updatedAt" = NOW()
