UPDATE "QuestionBankItem" SET
  explanation = $e13$Fever, cervical motion tenderness, and mucopurulent discharge in a sexually active young woman are pelvic inflammatory disease. Gonorrhea and chlamydia are the most common causes, so treatment is empiric antibiotics that cover both, and partners should be tested. More severe illness, including a tubo-ovarian abscess or pregnancy, is managed in the hospital.$e13$, "references" = $r13$[{"label": "MedlinePlus. Pelvic inflammatory disease is often caused by gonorrhea and chlamydia and is treated with antibiotics. Partners should be tested.", "url": "https://medlineplus.gov/pelvicinflammatorydisease.html"}]$r13$::jsonb, manual_correction = true, "generationMeta" = CASE WHEN "generationMeta" IS NULL THEN '{"manualCorrection": true}'::jsonb WHEN jsonb_typeof("generationMeta")='object' THEN jsonb_set("generationMeta", '{manualCorrection}', 'true'::jsonb, true) ELSE "generationMeta" END, "updatedAt" = NOW()
