UPDATE "QuestionBankItem" SET
  explanation = $e14$This is an acute ischemic stroke: sudden hemiparesis and aphasia, a normal head CT, and last known well 70 minutes ago. Thrombolysis within 4.5 hours is established practice, and no benefit has been shown beyond 4.5 hours. Blood pressure is 178/96 mm Hg, under the usual 185/110 mm Hg ceiling, so intravenous alteplase is appropriate if the remaining eligibility criteria are met, followed by stroke-unit care.$e14$, "references" = $r14$[{"label": "Open-access review, 30 years of thrombolysis for ischaemic stroke (PMC13725878). Thrombolysis within 4.5 hours is routine, and no benefit was shown beyond 4.5 hours.", "url": "https://www.ebi.ac.uk/europepmc/webservices/rest/PMC13725878/fullTextXML"}]$r14$::jsonb, manual_correction = true, "generationMeta" = CASE WHEN "generationMeta" IS NULL THEN '{"manualCorrection": true}'::jsonb WHEN jsonb_typeof("generationMeta")='object' THEN jsonb_set("generationMeta", '{manualCorrection}', 'true'::jsonb, true) ELSE "generationMeta" END, "updatedAt" = NOW()
